# Generated by build.py from recipe.yml for recipe ftp-resume-a-dropped-download. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir site
head -c 200000 /dev/urandom > site/update.iso
head -c 65536 site/update.iso > update.iso
head -c 200000 /dev/urandom > site/image.iso
head -c 65536 site/image.iso > image.iso
head -c 300000 /dev/zero > other.iso
surl --allow-anonymous --directory site -v --log-file surl.log --fault "drop;stage=command;command=RETR;path=/update.iso;times=1" --fault "drop;stage=command;command=RETR;path=/image.iso;times=1" ftp://127.0.0.1:8080/ &
sleep 1
curl -sS -C - --retry 1 --retry-all-errors -o update.iso -w "%{num_retries} %{size_download}\n" ftp://127.0.0.1:8080/update.iso
kill $(jobs -p)
